// Flat, dot-namespaced translation keys (one file for the whole app, same
// spirit as the HTML prototype's t() helper) rather than the web app's
// per-component inline text objects - easier to keep in sync for an app
// this size. Supported locales match what the real site actually ships
// (CookieLocale in lbp/frontend/src/ui.tsx: en/ru/es/pt/fr/de/it/pl - the
// site itself got all 8 in an earlier patch) - the app was missing the
// last 5 of those until this pass restored them (see below).
//
// {{placeholder}} tokens are replaced by src/i18n/I18nContext.tsx's t().
// Every key must exist in `en` (the fallback); every other locale is a
// translation of that same string, not an independently maintained copy -
// keep them in sync when you change an English string.
//
// pt/fr/de/it/pl were originally added 2026-09-15 (machine-translated,
// same process as the original ru/es sets, not yet reviewed by a native
// speaker) but that patch was never actually applied to this repo - only
// its two sibling patches (site 8-language infra, admin language tabs)
// were. Re-added 2026-09-16 after Alena flagged the gap, this time
// verified against a fresh clone before delivery. Also backfilled
// translations for every English key added since 2026-09-15 (the one-time
// purchases feature, and this session's own new AI-feature keys) that the
// original 5-language patch predates.

export type Locale = "en" | "ru" | "es" | "pt" | "fr" | "de" | "it" | "pl";

export const SUPPORTED_LOCALES: { code: Locale; label: string }[] = [
  { code: "en", label: "English" },
  { code: "ru", label: "Русский" },
  { code: "es", label: "Español" },
  { code: "pt", label: "Português" },
  { code: "fr", label: "Français" },
  { code: "de", label: "Deutsch" },
  { code: "it", label: "Italiano" },
  { code: "pl", label: "Polski" },
];

