  "nav.trustSafetyTitle": "Trust & Safety",
  "trustSafety.intro": "Building a family means trusting the people you meet along the way. Here's what LetsBeParents verifies before you connect, and what's still on you to check for yourself.",
  "trustSafety.check1Heading": "Identity verification",
  "trustSafety.check1Body": "Before unlocking full access to matches, members confirm their identity through a secure document check, handled by our verification partner, Didit. We don't store your ID document or selfie on LetsBeParents' own servers - that data is processed and retained by Didit under their own privacy terms, and can be deleted on request.",
  "trustSafety.check2Heading": "Photo review",
  "trustSafety.check2Body": "Every profile photo is automatically screened for policy violations, and any photo you report is reviewed by our team.",
  "trustSafety.check3Heading": "Private messaging & video",
  "trustSafety.check3Body": "Chat and video calls happen inside LetsBeParents. Your phone number and email stay private until you choose to share them.",
  "trustSafety.check4Heading": "Vetted clinics & lawyers",
  "trustSafety.check4Body": "Every clinic and lawyer in our directory is reviewed before it's listed, so you're never guessing who you're contacting.",
  "trustSafety.check5Heading": "Report & block, anytime",
  "trustSafety.check5Body": "You can report or block any member in one tap. Every report is reviewed by our team, not a bot.",
  "trustSafety.check6Heading": "Data protection",
  "trustSafety.check6Body": "Your data is encrypted in transit and at rest. We never sell your information, and you control what's visible on your profile.",
  "trustSafety.noteHeading": "What verification means - and what it doesn't",
  "trustSafety.noteBody": "Identity and photo checks reduce fake and duplicate profiles, but they aren't a medical, legal, or background-check guarantee. We strongly recommend independent legal advice before any donor or co-parenting agreement, and meeting new connections for the first time in a public place.",
