  "familyPlanPicker.title": "С кем планировать семью",
  "familyPlanPicker.subtitle": "У вас несколько реальных совпадений. Выберите, с кем открыть Семейный план.",
  "nav.compatibilityAnswersTitle": "Анкета совместимости",
  "nav.compatibilityReportTitle": "Отчёт о совместимости",
  "nav.explore": "Главная",
  "nav.knowledgeHubTitle": "База знаний",
  "nav.termsTitle": "Условия использования и конфиденциальность",
  "nav.trustSafetyTitle": "Доверие и безопасность",
  "trustSafety.intro": "Создание семьи - это доверие к людям, которых вы встречаете на этом пути. Вот что LetsBeParents проверяет перед тем, как вы начнёте общаться, и что вам всё же стоит проверить самостоятельно.",
  "trustSafety.check1Heading": "Проверка личности",
  "trustSafety.check1Body": "Прежде чем получить полный доступ к подбору пар, участники подтверждают личность через безопасную проверку документов - её проводит наш партнёр по верификации, сервис Didit. Мы не храним ваш документ или селфи на своих серверах - эти данные обрабатывает и хранит Didit по своим собственным условиям конфиденциальности, и их можно удалить по запросу.",
  "trustSafety.check2Heading": "Проверка фотографий",
  "trustSafety.check2Body": "Каждое фото профиля автоматически проверяется на нарушения правил, а фото, на которое поступила жалоба, проверяет наша команда.",
  "trustSafety.check3Heading": "Приватные сообщения и видеозвонки",
  "trustSafety.check3Body": "Переписка и видеозвонки происходят внутри LetsBeParents. Ваш номер телефона и email остаются приватными, пока вы сами не решите ими поделиться.",
  "trustSafety.check4Heading": "Проверенные клиники и юристы",
  "trustSafety.check4Body": "Каждая клиника и юрист в нашем каталоге проходят проверку перед публикацией - вам не нужно гадать, с кем вы связываетесь.",
  "trustSafety.check5Heading": "Жалоба и блокировка в любой момент",
  "trustSafety.check5Body": "Вы можете пожаловаться на участника или заблокировать его одним нажатием. Каждую жалобу рассматривает наша команда, а не бот.",
  "trustSafety.check6Heading": "Защита данных",
  "trustSafety.check6Body": "Ваши данные шифруются при передаче и хранении. Мы никогда не продаём вашу информацию, и вы сами решаете, что видно в вашем профиле.",
  "trustSafety.noteHeading": "Что означает проверка - а что нет",
  "trustSafety.noteBody": "Проверка личности и фотографий снижает число фейковых и дублирующихся профилей, но не является медицинской, юридической гарантией или полной проверкой биографии. Мы настоятельно рекомендуем получить независимую юридическую консультацию перед любым донорским или со-родительским соглашением и встречаться с новыми знакомыми впервые в общественном месте.",
  "nav.filtersTitle": "Фильтры",
  "nav.editProfileTitle": "Редактировать профиль",
