  "trustSafety.intro": "Formar una familia significa confiar en las personas que conoces en el camino. Esto es lo que LetsBeParents verifica antes de que conectes, y lo que sigue dependiendo de ti comprobar.",
  "trustSafety.check1Heading": "Verificación de identidad",
  "trustSafety.check1Body": "Antes de desbloquear el acceso completo a los matches, los miembros confirman su identidad mediante una comprobación segura de documentos, a cargo de nuestro socio de verificación, Didit. No almacenamos tu documento de identidad ni tu selfie en los servidores de LetsBeParents - esos datos los procesa y conserva Didit según sus propias condiciones de privacidad, y pueden eliminarse a petición.",
  "trustSafety.check2Heading": "Revisión de fotos",
  "trustSafety.check2Body": "Cada foto de perfil se analiza automáticamente en busca de infracciones, y cualquier foto reportada es revisada por nuestro equipo.",
  "trustSafety.check3Heading": "Mensajería y videollamadas privadas",
  "trustSafety.check3Body": "Los chats y videollamadas ocurren dentro de LetsBeParents. Tu teléfono y email permanecen privados hasta que decidas compartirlos.",
  "trustSafety.check4Heading": "Clínicas y abogados verificados",
  "trustSafety.check4Body": "Cada clínica y abogado de nuestro directorio se revisa antes de publicarse, así nunca tienes que adivinar con quién estás hablando.",
  "trustSafety.check5Heading": "Reporta o bloquea en cualquier momento",
  "trustSafety.check5Body": "Puedes reportar o bloquear a cualquier miembro con un toque. Cada reporte es revisado por nuestro equipo, no por un bot.",
  "trustSafety.check6Heading": "Protección de datos",
  "trustSafety.check6Body": "Tus datos se cifran en tránsito y en reposo. Nunca vendemos tu información, y tú controlas qué es visible en tu perfil.",
  "trustSafety.noteHeading": "Qué significa la verificación - y qué no",
  "trustSafety.noteBody": "Las verificaciones de identidad y fotos reducen los perfiles falsos y duplicados, pero no son una garantía médica, legal ni de antecedentes. Recomendamos encarecidamente obtener asesoría legal independiente antes de cualquier acuerdo de donación o co-parentalidad, y conocer en persona por primera vez en un lugar público.",
