  "nav.trustSafetyTitle": "Confiança e Segurança",
  "trustSafety.intro": "Construir uma família significa confiar nas pessoas que conhece pelo caminho. Eis o que a LetsBeParents verifica antes de se ligar a alguém, e o que ainda é da sua responsabilidade verificar.",
  "trustSafety.check1Heading": "Verificação de identidade",
  "trustSafety.check1Body": "Antes de desbloquear o acesso total às correspondências, os membros confirmam a sua identidade através de uma verificação segura de documentos, feita pelo nosso parceiro de verificação, a Didit. Não guardamos o seu documento de identificação nem a sua selfie nos servidores da própria LetsBeParents - esses dados são processados e conservados pela Didit segundo os seus próprios termos de privacidade, e podem ser eliminados a pedido.",
  "trustSafety.check2Heading": "Revisão de fotos",
  "trustSafety.check2Body": "Todas as fotos de perfil são automaticamente analisadas em busca de violações das regras, e qualquer foto que denuncie é revista pela nossa equipa.",
  "trustSafety.check3Heading": "Mensagens e vídeo privados",
  "trustSafety.check3Body": "As conversas e chamadas de vídeo acontecem dentro da LetsBeParents. O seu número de telefone e email mantêm-se privados até decidir partilhá-los.",
  "trustSafety.check4Heading": "Clínicas e advogados analisados",
  "trustSafety.check4Body": "Todas as clínicas e advogados no nosso diretório são analisados antes de serem listados, para que nunca tenha de adivinhar com quem está a contactar.",
  "trustSafety.check5Heading": "Denuncie e bloqueie, a qualquer momento",
  "trustSafety.check5Body": "Pode denunciar ou bloquear qualquer membro com um toque. Todas as denúncias são analisadas pela nossa equipa, não por um robô.",
  "trustSafety.check6Heading": "Proteção de dados",
  "trustSafety.check6Body": "Os seus dados são encriptados em trânsito e em repouso. Nunca vendemos as suas informações, e você controla o que é visível no seu perfil.",
  "trustSafety.noteHeading": "O que significa a verificação - e o que não significa",
  "trustSafety.noteBody": "As verificações de identidade e de fotos reduzem os perfis falsos e duplicados, mas não são uma garantia médica, legal ou de antecedentes. Recomendamos vivamente aconselhamento jurídico independente antes de qualquer acordo de doação ou de coparentalidade, e que se encontre pela primeira vez com novas ligações num local público.",
