  "nav.explore": "Explorer",
  "nav.knowledgeHubTitle": "Centre de ressources",
  "nav.termsTitle": "Conditions d'utilisation & Politique de confidentialité",
  "nav.trustSafetyTitle": "Confiance & sécurité",
  "trustSafety.intro": "Construire une famille suppose de faire confiance aux personnes que vous rencontrez en chemin. Voici ce que LetsBeParents vérifie avant que vous entriez en contact, et ce qu'il vous revient encore de vérifier vous-même.",
  "trustSafety.check1Heading": "Vérification d'identité",
  "trustSafety.check1Body": "Avant de débloquer l'accès complet aux matchs, les membres confirment leur identité via une vérification sécurisée de document, gérée par notre partenaire de vérification, Didit. Nous ne stockons pas votre pièce d'identité ni votre selfie sur les serveurs de LetsBeParents - ces données sont traitées et conservées par Didit selon ses propres conditions de confidentialité, et peuvent être supprimées sur demande.",
  "trustSafety.check2Heading": "Modération des photos",
  "trustSafety.check2Body": "Chaque photo de profil est automatiquement contrôlée pour détecter les infractions à nos règles, et toute photo que vous signalez est examinée par notre équipe.",
  "trustSafety.check3Heading": "Messagerie et vidéo privées",
  "trustSafety.check3Body": "Les discussions et appels vidéo se déroulent au sein de LetsBeParents. Votre numéro de téléphone et votre e-mail restent privés tant que vous ne choisissez pas de les partager.",
  "trustSafety.check4Heading": "Cliniques et avocats vérifiés",
  "trustSafety.check4Body": "Chaque clinique et chaque avocat de notre annuaire est examiné avant d'être répertorié, afin que vous ne deviniez jamais qui vous contactez.",
  "trustSafety.check5Heading": "Signaler et bloquer, à tout moment",
  "trustSafety.check5Body": "Vous pouvez signaler ou bloquer n'importe quel membre en un geste. Chaque signalement est examiné par notre équipe, pas par un robot.",
  "trustSafety.check6Heading": "Protection des données",
  "trustSafety.check6Body": "Vos données sont chiffrées en transit et au repos. Nous ne vendons jamais vos informations, et vous contrôlez ce qui est visible sur votre profil.",
  "trustSafety.noteHeading": "Ce que la vérification signifie - et ce qu'elle ne signifie pas",
  "trustSafety.noteBody": "Les contrôles d'identité et de photo réduisent les faux profils et les doublons, mais ne constituent pas une garantie médicale, juridique ou d'antécédents. Nous recommandons vivement de consulter un avocat indépendant avant tout accord de don ou de coparentalité, et de rencontrer une nouvelle connaissance pour la première fois dans un lieu public.",
  "nav.filtersTitle": "Filtres",
