  "verification.whyTitle": "Warum wir danach fragen",
  "verification.whyBody": "LetsBeParents ist ein Ort für echte Menschen, die echte Familien gründen - die Verifizierung ist eine der Möglichkeiten, wie wir das sicherstellen. Ein Verifizierungs-Badge zeigt anderen Mitgliedern, dass die Person, mit der sie sprechen, tatsächlich die ist, für die sie sich ausgibt - das ist hier noch wichtiger als bei einer typischen Dating-App.",
