  "agreement.signDisclaimer": "Dies ist ein nach Treu und Glauben geführter Nachweis zwischen Ihnen beiden, keine rechtlich bindende Unterschrift. Für eine durchsetzbare Vereinbarung wenden Sie sich an eine Fachperson für Familienrecht in Ihrer Region.",
