  "familyPlanPicker.title": "Mit wem eine Familie planen",
  "familyPlanPicker.subtitle": "Sie haben mehr als ein echtes Match. Wählen Sie, mit wem Sie den Familienplan öffnen möchten.",
  "nav.compatibilityAnswersTitle": "Kompatibilitätsprofil",
  "nav.compatibilityReportTitle": "Kompatibilitätsbericht",
  "nav.explore": "Entdecken",
  "nav.knowledgeHubTitle": "Wissensdatenbank",
  "nav.termsTitle": "Nutzungsbedingungen & Datenschutzerklärung",
  "nav.trustSafetyTitle": "Vertrauen & Sicherheit",
  "trustSafety.intro": "Eine Familie zu gründen bedeutet, den Menschen zu vertrauen, denen Sie auf diesem Weg begegnen. Hier erfahren Sie, was LetsBeParents überprüft, bevor Sie sich verbinden, und was Sie weiterhin selbst prüfen sollten.",
  "trustSafety.check1Heading": "Identitätsprüfung",
  "trustSafety.check1Body": "Bevor Mitglieder vollen Zugriff auf Matches erhalten, bestätigen sie ihre Identität durch eine sichere Dokumentenprüfung, die von unserem Verifizierungspartner Didit durchgeführt wird. Wir speichern Ihr Ausweisdokument oder Selfie nicht auf den eigenen Servern von LetsBeParents - diese Daten werden von Didit gemäß dessen eigenen Datenschutzbestimmungen verarbeitet und gespeichert und können auf Anfrage gelöscht werden.",
  "trustSafety.check2Heading": "Fotoprüfung",
  "trustSafety.check2Body": "Jedes Profilfoto wird automatisch auf Richtlinienverstöße geprüft, und jedes gemeldete Foto wird von unserem Team überprüft.",
  "trustSafety.check3Heading": "Private Nachrichten & Video",
  "trustSafety.check3Body": "Chat und Videoanrufe finden innerhalb von LetsBeParents statt. Ihre Telefonnummer und E-Mail-Adresse bleiben privat, bis Sie sich entscheiden, sie zu teilen.",
  "trustSafety.check4Heading": "Geprüfte Kliniken & Anwälte",
  "trustSafety.check4Body": "Jede Klinik und jeder Anwalt in unserem Verzeichnis wird vor der Aufnahme geprüft, sodass Sie nie raten müssen, mit wem Sie es zu tun haben.",
  "trustSafety.check5Heading": "Melden & blockieren, jederzeit",
  "trustSafety.check5Body": "Sie können jedes Mitglied mit einem Tipp melden oder blockieren. Jede Meldung wird von unserem Team geprüft, nicht von einem Bot.",
  "trustSafety.check6Heading": "Datenschutz",
  "trustSafety.check6Body": "Ihre Daten werden bei der Übertragung und im Ruhezustand verschlüsselt. Wir verkaufen Ihre Daten niemals, und Sie kontrollieren, was auf Ihrem Profil sichtbar ist.",
  "trustSafety.noteHeading": "Was Verifizierung bedeutet - und was nicht",
  "trustSafety.noteBody": "Identitäts- und Fotoprüfungen reduzieren gefälschte und doppelte Profile, sind aber keine Garantie für eine medizinische, rechtliche oder Hintergrundprüfung. Wir empfehlen dringend, vor jeder Spender- oder Co-Parenting-Vereinbarung unabhängigen rechtlichen Rat einzuholen und sich bei einem ersten Treffen mit neuen Kontakten an einem öffentlichen Ort zu treffen.",
  "nav.filtersTitle": "Filter",
