  "nav.termsTitle": "Termini e informativa sulla privacy",
  "nav.trustSafetyTitle": "Fiducia e sicurezza",
  "trustSafety.intro": "Costruire una famiglia significa fidarsi delle persone che incontra lungo il percorso. Ecco cosa verifica LetsBeParents prima che vi connettiate, e cosa spetta a Lei controllare personalmente.",
  "trustSafety.check1Heading": "Verifica dell'identità",
  "trustSafety.check1Body": "Prima di sbloccare l'accesso completo ai match, i membri confermano la propria identità tramite un controllo sicuro dei documenti, gestito dal nostro partner di verifica, Didit. Non conserviamo il Suo documento d'identità o selfie sui server di LetsBeParents - questi dati vengono elaborati e conservati da Didit secondo i propri termini sulla privacy, e possono essere eliminati su richiesta.",
  "trustSafety.check2Heading": "Revisione delle foto",
  "trustSafety.check2Body": "Ogni foto profilo viene controllata automaticamente per eventuali violazioni delle norme, e qualsiasi foto segnalata viene esaminata dal nostro team.",
  "trustSafety.check3Heading": "Messaggistica privata e video",
  "trustSafety.check3Body": "Chat e videochiamate avvengono all'interno di LetsBeParents. Il Suo numero di telefono e la Sua email restano privati finché non sceglie di condividerli.",
  "trustSafety.check4Heading": "Cliniche e avvocati selezionati",
  "trustSafety.check4Body": "Ogni clinica e avvocato nel nostro elenco viene verificato prima di essere inserito, così non deve mai indovinare con chi sta parlando.",
  "trustSafety.check5Heading": "Segnala e blocca, in qualsiasi momento",
  "trustSafety.check5Body": "Può segnalare o bloccare qualsiasi membro con un tocco. Ogni segnalazione viene esaminata dal nostro team, non da un bot.",
  "trustSafety.check6Heading": "Protezione dei dati",
  "trustSafety.check6Body": "I Suoi dati sono criptati durante la trasmissione e a riposo. Non vendiamo mai le Sue informazioni, e Lei controlla cosa è visibile sul Suo profilo.",
  "trustSafety.noteHeading": "Cosa significa la verifica - e cosa non significa",
  "trustSafety.noteBody": "I controlli su identità e foto riducono i profili falsi e duplicati, ma non sono una garanzia medica, legale o di controllo dei precedenti. Consigliamo vivamente una consulenza legale indipendente prima di qualsiasi accordo di donazione o co-genitorialità, e di incontrare per la prima volta nuove connessioni in un luogo pubblico.",
  "nav.filtersTitle": "Filtri",
