  "costCalc.disclaimer": "Questi sono solo intervalli di riferimento indicativi per il mercato statunitense, non preventivi. I costi reali variano enormemente in base al paese, al fornitore e alle circostanze individuali - richieda sempre un preventivo scritto prima di impegnarsi in qualsiasi cosa.",
