  "costCalc.path.knownDonor.title": "Donatore conosciuto (inseminazione domestica)",
  "costCalc.path.knownDonor.desc": "Concepimento con un donatore che già conosce, senza una clinica della fertilità.",
  "costCalc.path.knownDonor.tip": "Un accordo legale con un donatore conosciuto, anche tra amici, protegge i diritti genitoriali di tutti in futuro - non lo salti.",
  "costCalc.path.cryobankIui.title": "Banca dello sperma + IUI",
  "costCalc.path.cryobankIui.desc": "Una fiala di donatore da una banca autorizzata, inseminata presso una clinica.",
  "costCalc.path.cryobankIui.tip": "Molte persone hanno bisogno di 3-6 cicli prima di una gravidanza - pianificare il budget per diversi tentativi fin dall'inizio evita sorprese.",
  "costCalc.path.ivfOwnEggs.title": "FIVET (con i Suoi ovuli)",
  "costCalc.path.ivfOwnEggs.desc": "Fecondazione in vitro utilizzando i Suoi ovuli e sperma proprio o di un donatore.",
  "costCalc.path.ivfOwnEggs.tip": "Chieda a ogni clinica un preventivo dettagliato - un prezzo forfettario per il 'pacchetto FIVET' spesso esclude farmaci e test genetici.",
  "costCalc.path.ivfDonorEggs.title": "FIVET con ovuli donati",
  "costCalc.path.ivfDonorEggs.desc": "Fecondazione in vitro utilizzando ovuli di una donatrice.",
  "costCalc.path.ivfDonorEggs.tip": "Gli ovuli donati congelati (da banca) sono in genere più economici rispetto a un ciclo fresco abbinato specificamente a Lei - vale la pena chiedere entrambi i prezzi.",
  "costCalc.path.surrogacy.title": "Maternità surrogata gestazionale",
  "costCalc.path.surrogacy.desc": "Una madre surrogata porta avanti una gravidanza creata con il Suo embrione.",
  "costCalc.path.surrogacy.tip": "Richieda una consulenza legale separata per Lei e per la madre surrogata - quasi ogni paese/stato lo richiede, e protegge entrambe le parti.",
  "costCalc.path.domesticAdoption.title": "Adozione nazionale",
  "costCalc.path.domesticAdoption.desc": "Adottare un bambino nato nel Suo stesso paese.",
  "costCalc.path.domesticAdoption.tip": "I costi variano enormemente in base all'agenzia - richieda un elenco completo delle spese scritto prima di impegnarsi.",
  "costCalc.path.internationalAdoption.title": "Adozione internazionale",
  "costCalc.path.internationalAdoption.desc": "Adottare un bambino da un altro paese.",
  "costCalc.path.internationalAdoption.tip": "I tempi possono variare da 1 a 3 anni - consideri più viaggi e possibili soggiorni prolungati all'estero.",
  "costCalc.path.fosterAdopt.title": "Affido con adozione",
  "costCalc.path.fosterAdopt.desc": "Accogliere un bambino in affido attraverso il sistema statale, con l'adozione come obiettivo.",
  "costCalc.path.fosterAdopt.tip": "In molti paesi questo percorso è sovvenzionato dallo stato e notevolmente più economico dei percorsi privati - vale la pena esplorarlo se il costo è l'ostacolo principale.",
