  "verification.whyTitle": "Dlaczego o to prosimy",
  "verification.whyBody": "LetsBeParents to miejsce dla prawdziwych osób budujących prawdziwe rodziny - weryfikacja to jeden ze sposobów, by tak pozostało. Zweryfikowana odznaka informuje innych użytkowników, że rozmawiają z osobą, za którą się podaje - a to ma tu jeszcze większe znaczenie niż w typowej aplikacji randkowej.",
  "verification.poweredBy": "Weryfikacją tożsamości zajmuje się nasz partner Didit - dane nie są przechowywane ani przeglądane bezpośrednio przez nas.",
