  "familyPlanPicker.title": "Z kim zaplanować rodzinę",
  "familyPlanPicker.subtitle": "Masz więcej niż jedno prawdziwe dopasowanie. Wybierz, z kim otworzyć Plan rodzinny.",
  "nav.compatibilityAnswersTitle": "Profil kompatybilności",
