  "nav.termsTitle": "Regulamin i Polityka prywatności",
  "nav.trustSafetyTitle": "Zaufanie i bezpieczeństwo",
  "trustSafety.intro": "Budowanie rodziny oznacza zaufanie do osób poznawanych po drodze. Oto co LetsBeParents weryfikuje, zanim nastąpi kontakt, oraz co nadal warto sprawdzić samodzielnie.",
  "trustSafety.check1Heading": "Weryfikacja tożsamości",
  "trustSafety.check1Body": "Przed odblokowaniem pełnego dostępu do dopasowań użytkownicy potwierdzają tożsamość poprzez bezpieczną kontrolę dokumentu, obsługiwaną przez naszego partnera weryfikacyjnego, Didit. Nie przechowujemy dokumentu tożsamości ani selfie na własnych serwerach LetsBeParents - te dane są przetwarzane i przechowywane przez Didit zgodnie z jego własnymi warunkami prywatności i mogą zostać usunięte na żądanie.",
  "trustSafety.check2Heading": "Kontrola zdjęć",
  "trustSafety.check2Body": "Każde zdjęcie profilowe jest automatycznie sprawdzane pod kątem naruszeń zasad, a każde zgłoszone zdjęcie jest przeglądane przez nasz zespół.",
  "trustSafety.check3Heading": "Prywatne wiadomości i wideo",
  "trustSafety.check3Body": "Czat i połączenia wideo odbywają się wewnątrz LetsBeParents. Numer telefonu i adres e-mail pozostają prywatne, dopóki użytkownik nie zdecyduje się je udostępnić.",
  "trustSafety.check4Heading": "Zweryfikowane kliniki i kancelarie prawne",
  "trustSafety.check4Body": "Każda klinika i kancelaria prawna w naszym katalogu jest sprawdzana przed dodaniem do listy, więc nigdy nie trzeba zgadywać, z kim się kontaktuje.",
  "trustSafety.check5Heading": "Zgłaszanie i blokowanie w każdej chwili",
  "trustSafety.check5Body": "Każdego użytkownika można zgłosić lub zablokować jednym dotknięciem. Każde zgłoszenie jest sprawdzane przez nasz zespół, nie przez bota.",
  "trustSafety.check6Heading": "Ochrona danych",
  "trustSafety.check6Body": "Dane są szyfrowane podczas przesyłania i przechowywania. Nigdy nie sprzedajemy informacji, a każdy użytkownik kontroluje, co jest widoczne na jego profilu.",
  "trustSafety.noteHeading": "Co oznacza weryfikacja - a czego nie oznacza",
  "trustSafety.noteBody": "Kontrola tożsamości i zdjęć ogranicza liczbę fałszywych i zduplikowanych profili, ale nie stanowi gwarancji medycznej, prawnej ani wywiadu środowiskowego. Zdecydowanie zalecamy niezależną poradę prawną przed każdą umową dawstwa lub współrodzicielstwa oraz spotykanie nowych kontaktów po raz pierwszy w miejscu publicznym.",
